using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;
// 0.115 (read-only, temporary): colliders near a point (PROBE_NEAR "scene:x,z,r")
public static class Report115Near { public static void Run(){var o=Environment.GetEnvironmentVariable("PROBE_OUT");Directory.CreateDirectory(o);var a=Environment.GetEnvironmentVariable("PROBE_NEAR").Split(':');var f=a[1].Split(',').Select(x=>float.Parse(x,System.Globalization.CultureInfo.InvariantCulture)).ToArray();
 EditorSceneManager.OpenScene("Assets/Scenes/"+a[0]+".unity");
 File.WriteAllLines(Path.Combine(o,"near.txt"),UnityEngine.Object.FindObjectsByType<Collider>(FindObjectsInactive.Include,FindObjectsSortMode.None).Where(c=>{var b=c.bounds;return Mathf.Abs(b.center.x-f[0])<f[2]+b.extents.x&&Mathf.Abs(b.center.z-f[1])<f[2]+b.extents.z&&b.size.magnitude<40;}).Select(c=>$"{c.GetType().Name} '{c.name}' parent '{c.transform.parent?.name}' enabled {c.enabled} active {c.gameObject.activeInHierarchy} bounds {c.bounds.min} {c.bounds.max} comps {string.Join(";",c.GetComponents<Component>().Select(x=>x.GetType().Name))} children {c.transform.childCount}"));EditorApplication.Exit(0);}}
